import React, { useState } from "react";
import { Routes, Route } from "react-router-dom";
import { Leaf } from "lucide-react";
import Header from "./components/Header";
import CartDrawer from "./components/CartDrawer";
import Home from "./pages/Home";
import Menu from "./pages/Menu";
import Login from "./pages/Login";
import Register from "./pages/Register";
import Checkout from "./pages/Checkout";
import OrderTracking from "./pages/OrderTracking";
import MyOrders from "./pages/MyOrders";
import Admin from "./pages/Admin";

export default function App() {
  const [cartOpen, setCartOpen] = useState(false);

  return (
    <>
      <Header onCartClick={() => setCartOpen(true)} />

      <Routes>
        <Route path="/" element={<Home />} />
        <Route path="/menu" element={<Menu />} />
        <Route path="/login" element={<Login />} />
        <Route path="/register" element={<Register />} />
        <Route path="/checkout" element={<Checkout />} />
        <Route path="/orders" element={<MyOrders />} />
        <Route path="/orders/:orderId" element={<OrderTracking />} />
        <Route path="/admin" element={<Admin />} />
      </Routes>

      <Footer />

      {cartOpen && <CartDrawer onClose={() => setCartOpen(false)} />}
    </>
  );
}

function Footer() {
  return (
    <footer style={{ borderTop: "1px solid var(--border)", marginTop: 20 }}>
      <div className="container" style={{ padding: "26px 24px", display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: 10 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 8, color: "var(--forest-dark)", fontWeight: 700 }}>
          <Leaf size={15} color="var(--forest)" /> Healthy Food
        </div>
        <div style={{ fontSize: 13, color: "var(--ink-faint)" }}>© {new Date().getFullYear()} Healthy Food · Fresh, tracked, delivered.</div>
      </div>
    </footer>
  );
}
